  async function addEasyDrop({name,feedUrl}){await action('add-easydrop',()=>api('/api/admin/suppliers',{method:'POST',body:{provider:'easydrop',name,feedUrl,enabled:true}}),'Постачальника EasyDrop додано. Синхронізація EasyDrop може бути ще недоступна.');}
