  async function deleteSupplier(supplier){setBusy(`delete-${supplier.id}`);onError('');onSuccess('');try{const result=await api(`/api/admin/suppliers/${encodeURIComponent(supplier.id)}`,{method:'DELETE',body:{confirm:true}});onSuccess(`Постачальника переміщено до кошика. Приховано пов’язаних товарів: ${result.affectedProducts}; раніше опублікованих: ${result.publishedProducts}. Підключення постачальника не змінено.`);}catch(e){onError(e.message);throw e;}finally{await onRefresh();setBusy('');}}
