  const o=p.overrides||{},s=p.source||{},suggestion=p.classificationSuggestion||{categoryId:p.categoryId||'unclassified',category:p.category||'Без категорії',categoryPath:p.categoryPath||[],brand:p.brand||null,confidence:'low',reasons:['Серверна пропозиція недоступна. Оновіть каталог перед автоматичним визначенням.']};
  const [categoryChoice,setCategoryChoice]=useState((o.categoryId?getCategory(o.categoryId)?.id:null)??(o.category?'__legacy__':'__auto__')), [brandAuto,setBrandAuto]=useState(o.brand==null);
  const [form,setForm] = useState({brand:p.brand||'',title:p.title||'',description:p.description||'',category:p.category||'',slug:p.slug||'',published:!!p.published,markupType:o.markupType||'fixed',markupValue:(o.markupValue||0)/(o.markupType==='percent'?1:100),photos:(p.photos||[]).join('\n'),hiddenSizes:o.hiddenSizes||[],promoText:o.promoText||'',freeShipping:!!o.freeShipping,promoStartsAt:localDate(o.promoStartsAt),promoEndsAt:localDate(o.promoEndsAt),seoTitle:o.seoTitle||'',seoDescription:o.seoDescription||'',priceOverride:minorToInput(o.priceOverrideMinor),tags:p.tags||[]});
