  const [busy,setBusy]=useState(false),[uploading,setUploading]=useState(false),[error,setError]=useState(''),[activeTab,setActiveTab]=useState(initialTab==='source'&&manual?'source':['content','photos','promo','seo'].includes(initialTab)?initialTab:'content'),[resetPhotos,setResetPhotos]=useState(o.photos == null);
