    if(!Number.isFinite(markupValue)||markupValue<0||!Number.isInteger(markupValue))throw new Error('Націнка має бути невід’ємним значенням. Відсоток — ціле число.');
    const patch={...form,title:form.title===s.title?null:form.title,description:form.description===s.description?null:form.description,category:form.category===s.category?null:form.category,markupValue,photos:resetPhotos?null:form.photos.split('\n').map(x=>x.trim()).filter(Boolean),promoStartsAt:form.promoStartsAt?new Date(form.promoStartsAt).toISOString():null,promoEndsAt:form.promoEndsAt?new Date(form.promoEndsAt).toISOString():null};
    if(patch.promoStartsAt&&patch.promoEndsAt&&patch.promoStartsAt>=patch.promoEndsAt)throw new Error('Дата завершення акції має бути після дати початку.');
